:root{--bg:#0b0e0d;--fg:#e6efe9;--mute:#8aa094;--line:#1f2b25;--card:#111814;--soft:#172119;--accent:#7dd3a8;--mint:#b4f5d1;--deep:#3aa876;--accent-ink:#08150e;--err:#e5484d;color-scheme:dark light;--sans:ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,Inter,sans-serif;--mono:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}
@media (prefers-color-scheme:light){:root{--bg:#f4f9f6;--fg:#15201a;--mute:#5d7367;--line:#d5e5db;--card:#fff;--soft:#e9f3ed;--accent:#2f8f63;--mint:#1f6f4a;--deep:#256e4c;--accent-ink:#f2fbf6}}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font:15.5px/1.6 var(--sans)}a{color:var(--accent);text-decoration:none}a:hover{text-decoration:underline;text-underline-offset:3px}
main{max-width:66rem;margin:0 auto;padding:2rem 1.25rem 3.5rem;display:grid;grid-template-columns:minmax(0,1fr) 23rem;column-gap:2.25rem;align-items:start;animation:fade .4s ease-out}@keyframes fade{from{opacity:0;transform:translateY(5px)}}
@media (prefers-reduced-motion:reduce){main{animation:none}.dot.open{animation:none}.item:hover,.courses li:hover{transform:none}}
header.me,details.fold,footer{grid-column:1/-1}section.c{grid-column:1;margin-top:1.75rem}
#chat{grid-column:2;grid-row:3/span 12;position:sticky;top:1rem;margin-top:1.75rem}
header.me{display:flex;gap:1.1rem;align-items:flex-start;padding:1.25rem 1.35rem;border-radius:18px;border:1px solid var(--line);background:radial-gradient(120% 160% at 0% 0%,color-mix(in srgb,var(--accent) 22%,transparent),transparent 62%),var(--card);position:relative}
header.me img{width:56px;height:56px;border-radius:15px;flex:none;box-shadow:0 8px 24px color-mix(in srgb,var(--accent) 25%,transparent)}header.me .who{min-width:0}
header.me h1{font-size:1.7rem;line-height:1.15;margin:0 0 .25rem;letter-spacing:-.01em}header.me .line{margin:0;color:var(--mute);font-size:.98rem}
.pills{display:flex;flex-wrap:wrap;gap:.4rem;margin-top:.75rem}.pill{font:inherit;font-size:.74rem;line-height:1.2;padding:.3rem .7rem;border-radius:999px;border:1px solid color-mix(in srgb,var(--accent) 35%,var(--line));background:color-mix(in srgb,var(--accent) 9%,transparent);color:var(--fg);cursor:pointer}.pill:hover{text-decoration:none;background:color-mix(in srgb,var(--accent) 20%,transparent);border-color:var(--accent)}
details.fold{margin-top:1rem;border:1px solid var(--line);border-radius:14px;background:var(--card)}details.fold>summary{cursor:pointer;list-style:none;display:flex;align-items:center;gap:.6rem;padding:.7rem 1rem;font-size:.82rem;color:var(--mute)}details.fold>summary::-webkit-details-marker{display:none}
details.fold>summary::before{content:"▸";color:var(--accent);font-size:.8rem;transition:transform .15s}details.fold[open]>summary::before{transform:rotate(90deg)}details.fold>summary .grow{flex:1}details.fold>.md{padding:.25rem 1rem 1rem}
#courses.fold{background:linear-gradient(90deg,color-mix(in srgb,var(--accent) 12%,var(--card)),var(--card))}
.label{display:flex;align-items:baseline;gap:.6rem;margin:0 0 .9rem;padding-bottom:.45rem;border-bottom:1px solid color-mix(in srgb,var(--accent) 30%,var(--line));font-size:.72rem;letter-spacing:.14em;text-transform:uppercase;color:var(--accent);font-weight:700}.label .grow{flex:1}
.ev{font-weight:400;letter-spacing:0;text-transform:none;font-size:.72rem;opacity:.55;color:var(--mute)}.ev:hover{opacity:1;text-decoration:none;color:var(--mint)}
.draft{font-size:.62rem;color:var(--accent);border:1px dashed var(--accent);border-radius:4px;padding:0 .3rem;letter-spacing:0;text-transform:none;font-weight:500;margin-left:.4rem}
.md p{margin:0 0 1rem}.md>:last-child{margin-bottom:0}.md h1,.md h2,.md h3{font-size:1.02rem;margin:1.4rem 0 .5rem}.md ul,.md ol{padding-left:1.3rem;margin:0 0 1rem}.md li{margin:.15rem 0}
.md code{font:.88em var(--mono);background:var(--soft);padding:.1em .35em;border-radius:4px}.md pre{background:var(--soft);padding:1rem;border-radius:8px;overflow:auto}.md pre code{background:none;padding:0}.md img{max-width:100%;border-radius:8px}
.md blockquote{margin:0 0 1rem;padding-left:1rem;border-left:2px solid var(--line);color:var(--mute)}.md hr{border:0;border-top:1px solid var(--line);margin:1.5rem 0}
.courses{display:grid;grid-template-columns:repeat(auto-fill,minmax(13.5rem,1fr));gap:.45rem;list-style:none;margin:.75rem 0 0;padding:0}
.courses li{font-size:.76rem;line-height:1.3;padding:.42rem .6rem;border-radius:8px;border:1px solid color-mix(in srgb,var(--accent) 24%,transparent);background:color-mix(in srgb,var(--accent) var(--g,8%),transparent);transition:transform .15s}.courses li:hover{transform:translateY(-1px)}
.courses li b{display:block;font:600 .64rem var(--mono);letter-spacing:.05em;color:var(--accent);margin-bottom:.12rem}.courses .y1{--g:6%}.courses .y2{--g:13%}.courses .y3{--g:21%}.courses .y4{--g:31%}
.courses .other{border-color:var(--line);background:var(--soft)}.courses .other b{color:var(--mute)}.legend{font-size:.72rem;color:var(--mute);margin:.6rem 0 0}
.items{list-style:none;margin:0;padding:0;display:grid;gap:.85rem}
.item{display:flex;flex-wrap:wrap;gap:.9rem 1rem;align-items:flex-start;padding:.9rem;border-radius:14px;border:1px solid var(--line);background:linear-gradient(135deg,color-mix(in srgb,var(--accent) 10%,var(--card)),var(--card) 70%);transition:transform .15s,border-color .15s,box-shadow .15s}
.item:hover{transform:translateY(-2px);border-color:color-mix(in srgb,var(--accent) 45%,var(--line));box-shadow:0 10px 30px color-mix(in srgb,var(--accent) 12%,transparent)}
#writing .item{background:linear-gradient(135deg,color-mix(in srgb,var(--deep) 22%,var(--card)),var(--card) 70%)}
.thumb{flex:none;line-height:0;border-radius:9px}.thumb .th{width:132px;height:84px;object-fit:cover;object-position:top;border-radius:9px;border:1px solid var(--line);background:var(--soft);transition:transform .2s}.item:hover .thumb .th{transform:scale(1.03)}
#writing .thumb .th{width:88px;height:114px;background:#fff;box-shadow:0 6px 18px rgba(0,0,0,.25)}
.thumb.ph{display:grid;place-items:center;width:132px;height:84px;border:1px solid var(--line);background:var(--soft);color:var(--accent);font-size:1.3rem;line-height:1}.thumb.ph:hover{text-decoration:none;background:color-mix(in srgb,var(--accent) 14%,transparent)}
.preview{flex-basis:100%;width:100%;height:34rem;border:1px solid var(--line);border-radius:10px;background:#fff}
.item .b{min-width:0;flex:1;font-size:.93rem}.item .t{font-weight:650;font-size:1.02rem}.item .t a{color:var(--fg)}.item .t a:hover{color:var(--mint)}.item .s{color:var(--mute);margin:.1rem 0 .3rem}.item .md{font-size:.88rem}.item .meta,.note .meta{display:flex;gap:.6rem;align-items:center;margin-top:.3rem;font-size:.72rem;color:var(--mute)}
.note{padding:.9rem 0;border-top:1px solid var(--line)}.note:first-of-type{border-top:0;padding-top:0}.note time{display:block;font-size:.74rem;color:var(--mute);margin-bottom:.2rem}
footer{margin-top:2.5rem;padding-top:1rem;border-top:1px solid var(--line);font-size:.8rem;color:var(--mute)}
.status{display:flex;flex-wrap:wrap;gap:.4rem 1rem;align-items:center;font-size:.74rem}.dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--line);margin-right:.35rem;vertical-align:1px}
.dot.open{background:var(--accent);animation:pulse 2.6s ease-out infinite}@keyframes pulse{0%{box-shadow:0 0 0 0 color-mix(in srgb,var(--accent) 55%,transparent)}70%{box-shadow:0 0 0 6px transparent}100%{box-shadow:0 0 0 0 transparent}}.dot.err{background:var(--err)}
button{font:inherit;font-size:.85rem;color:var(--fg);background:var(--soft);border:1px solid var(--line);border-radius:8px;padding:.45rem .8rem;cursor:pointer;line-height:1.2}button:hover{border-color:var(--accent)}
button.pri{background:var(--accent);color:var(--accent-ink);border-color:transparent;font-weight:600}button.pri:hover{background:var(--mint)}button.sm{font-size:.72rem;padding:.22rem .5rem}button.lnk{background:none;border:0;padding:0;color:var(--accent);font-size:inherit}button.lnk:hover{text-decoration:underline}button.danger{color:var(--err)}button:disabled{opacity:.5;cursor:default}
input,textarea{font:inherit;color:var(--fg);background:var(--bg);border:1px solid var(--line);border-radius:8px;padding:.5rem .65rem;width:100%}textarea{min-height:5rem;resize:vertical;font-size:.92rem}input:focus,textarea:focus{outline:none;border-color:var(--accent);box-shadow:0 0 0 3px color-mix(in srgb,var(--accent) 18%,transparent)}
.row{display:flex;gap:.5rem;margin-top:1rem;flex-wrap:wrap;align-items:center}.empty{color:var(--mute);font-size:.9rem;margin:0}
.chat{border:1px solid color-mix(in srgb,var(--accent) 30%,var(--line));border-radius:14px;background:var(--card);overflow:hidden;box-shadow:0 12px 40px color-mix(in srgb,var(--accent) 8%,transparent)}
.chat .who{display:flex;gap:.6rem;align-items:center;flex-wrap:wrap;padding:.6rem .8rem;border-bottom:1px solid var(--line);font-size:.8rem;color:var(--mute);background:color-mix(in srgb,var(--accent) 8%,transparent)}.chat .who input{max-width:11rem;padding:.3rem .5rem;font-size:.85rem}
.chat .log{max-height:22rem;overflow:auto;padding:.9rem;display:flex;flex-direction:column;gap:.45rem}.chat .hint{font-size:.8rem;color:var(--mute);padding:.9rem;border-bottom:1px solid var(--line)}
.msg{max-width:86%;padding:.5rem .75rem;border-radius:12px;background:var(--soft);font-size:.9rem;white-space:pre-wrap;word-break:break-word;align-self:flex-start;border-bottom-left-radius:3px}.msg.out{align-self:flex-end;background:var(--accent);color:var(--accent-ink);border-bottom-left-radius:12px;border-bottom-right-radius:3px}.msg small{display:block;font-size:.66rem;opacity:.65;margin-top:.15rem}
.chat form{display:flex;gap:.5rem;padding:.65rem .8rem;border-top:1px solid var(--line)}.chat form textarea{min-height:2.6rem;max-height:10rem}
.badge{display:inline-block;min-width:1.2em;padding:0 .35em;border-radius:999px;background:var(--accent);color:var(--accent-ink);font-size:.66rem;font-weight:700;margin-left:.35rem;vertical-align:1px;font-style:normal}.keys{padding:.5rem .8rem;border-top:1px solid var(--line);font-size:.74rem;color:var(--mute)}.keys summary{cursor:pointer}.keys .row{margin-top:.4rem}
.toasts{position:fixed;right:1rem;bottom:1rem;display:flex;flex-direction:column;gap:.4rem;z-index:40}.toast{background:var(--card);border:1px solid var(--line);border-radius:8px;padding:.5rem .8rem;font-size:.78rem;max-width:22rem;box-shadow:0 8px 30px rgba(0,0,0,.3)}.toast.err{border-color:var(--err)}
.spin{display:inline-block;width:.8em;height:.8em;border:2px solid var(--line);border-top-color:var(--accent);border-radius:50%;animation:spin .8s linear infinite;vertical-align:-1px;margin-right:.35rem}@keyframes spin{to{transform:rotate(360deg)}}
@media (max-width:900px){main{grid-template-columns:1fr;padding:1.5rem 1rem 3rem}header.me{order:-3}#courses.fold{order:-2}#chat{order:-1;grid-column:1;grid-row:auto;position:static}section.c{grid-column:1}header.me{gap:.9rem}.thumb .th,.thumb.ph{width:104px;height:66px}#writing .thumb .th{width:72px;height:94px}}
